fields.InputDefinition:
{
  "goal": "Open the 'Products' entity grid — type 'Products' in the LEFT sidebar 'Search entities...' box and click the exact match (or navigate to http://localhost:4200/app/data-explorer/Data?entity=Products). Wait for the grid to load. Then walk these grid/toolbar actions IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) grid-row-selection — select one or more rows using the row checkboxes at the left (use the header select-all checkbox to select multiple); confirm a selection count appears and/or selection-dependent toolbar actions become enabled (if the grid is empty a valid empty-state is acceptable); (2) grid-multi-column-sort — apply a sort on a column via the 'Sorting' control (up-wide-short icon) or by clicking a column header, and confirm the grid re-orders its rows with a sort indicator on the sorted column; (3) grid-more-actions-menu — click the 'More actions' control (vertical ellipsis / three-dots icon) in the toolbar and confirm an overflow menu opens listing additional actions; (4) grid-export-excel — click the 'Export to Excel' control (Excel-file icon) or 'Export' then Excel, and confirm the export initiates cleanly (a download begins, or an export options dialog / success toast appears) with no error — you do NOT need to open the downloaded file; (5) grid-bulk-add-to-list — with multiple rows selected, click the 'Add to List' toolbar button and confirm a bulk 'Add N Records to List' dialog opens (list search box, a New/Create List option, list selection or a valid empty state); (6) grid-recycle-bin — look for the Recycle Bin chip (trash-can-arrow-up icon) in the toolbar; if present click it and confirm the Recycle Bin slide-in panel opens showing deleted records with Restore buttons OR a valid 'Recycle Bin is empty' state (if the chip is legitimately absent, that is an acceptable outcome). Keep going until every action has been visited. You do NOT need to finalize any action. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200/app/data-explorer/Data?entity=Products",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 90,
  "checkpoints": [
    {
      "name": "grid-row-selection",
      "instruction": "open Products grid and select rows",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/data-explorer/Data"
        }
      ],
      "visualCriteria": [
        "The Products grid is loaded and selecting one or more rows via the checkboxes updates the selection state — a selection count appears and/or a selection-dependent toolbar control becomes enabled (or a valid empty-state renders if there are no rows)"
      ]
    },
    {
      "name": "grid-multi-column-sort",
      "instruction": "apply a column sort",
      "visualCriteria": [
        "A sort was applied to a grid column (via the Sorting panel or a column header) — the grid re-ordered its rows and shows a sort indicator on the sorted column"
      ]
    },
    {
      "name": "grid-more-actions-menu",
      "instruction": "open the More actions overflow menu",
      "visualCriteria": [
        "Clicking the grid's 'More actions' (vertical ellipsis) control opened an overflow menu listing additional actions"
      ]
    },
    {
      "name": "grid-export-excel",
      "instruction": "trigger Export to Excel",
      "visualCriteria": [
        "The grid's 'Export to Excel' (or Export→Excel) control was clicked and the export initiated cleanly — a download started, or an export dialog / success toast appeared, with no error"
      ]
    },
    {
      "name": "grid-bulk-add-to-list",
      "instruction": "open bulk Add-to-List dialog",
      "visualCriteria": [
        "With multiple rows selected, clicking 'Add to List' opened a bulk 'Add N Records to List' dialog showing a list search box, a New/Create List option, and list selection or a valid 'No lists yet' empty state"
      ]
    },
    {
      "name": "grid-recycle-bin",
      "instruction": "open the Recycle Bin restore panel",
      "visualCriteria": [
        "The Recycle Bin chip opened a slide-in panel titled 'Recycle Bin' showing deleted-record entries with Restore buttons OR a valid 'Recycle Bin is empty' state — OR the chip is legitimately absent (no deletions / no permission)"
      ]
    }
  ]
}
